// resolveDefaultGenerator creates a Generator based on settings.
// If the configured agent supports the Prompter interface, uses PrompterGenerator.
// Falls back to ClaudeGenerator for backward compatibility.
func resolveDefaultGenerator() *PrompterGenerator {
	s, err := settings.Load()
	if err != nil {
		return defaultPrompterGenerator()
	}

	agentName := agent.AgentName(s.SummarizeAgent())
	if agentName == "" {
		agentName = agent.DefaultAgentName
	}

	ag, err := agent.Get(agentName)
	if err != nil {
		return defaultPrompterGenerator()
	}

	prompter, ok := ag.(agent.Prompter)
	if !ok {
		return defaultPrompterGenerator()
	}

	return &PrompterGenerator{
		Prompter: prompter,
		Model:    s.SummarizeModel(),
	}
}

// defaultPrompterGenerator returns a PrompterGenerator using the default agent.
func defaultPrompterGenerator() *PrompterGenerator {
	ag, err := agent.Get(agent.DefaultAgentName)
	if err != nil {
		// Last resort: this shouldn't happen since claude-code is always registered
		return &PrompterGenerator{}
	}
	prompter, ok := ag.(agent.Prompter)
	if !ok {
		return &PrompterGenerator{}
	}
	return &PrompterGenerator{Prompter: prompter}
}

